-- 0001_init: the Phase 1 domain model.
--
-- Rules every table follows:
--   * Primary keys are random UUIDs generated by the application (models.BeforeCreate),
--     never sequences: unguessable in URLs, no write hotspot on CockroachDB (Phase 11b).
--   * Every tenant-owned row carries tenant_id itself, and its parent is referenced by a
--     composite foreign key (tenant_id, parent_id). The database then refuses a row
--     whose parent belongs to a different tenant, whatever the application code does.
--   * Statuses are text + CHECK, not Postgres ENUM types: adding a value is a one-line
--     constraint swap, and ENUMs are a portability problem (Phase 11b audit).

CREATE TABLE tenants (
    id         uuid        PRIMARY KEY,
    name       text        NOT NULL,
    -- Ends up in hostnames, so DNS-label rules: lowercase, digits, inner hyphens, <= 40.
    slug       text        NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$'),
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL
);

CREATE TABLE projects (
    id         uuid        PRIMARY KEY,
    tenant_id  uuid        NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
    name       text        NOT NULL CHECK (name ~ '^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$'),
    repo_url   text        NOT NULL,
    branch     text        NOT NULL,
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL,
    UNIQUE (tenant_id, name),
    -- Redundant as a uniqueness rule (id is already unique), but a foreign key can
    -- only point at columns covered by a unique constraint. This is that target.
    UNIQUE (tenant_id, id)
);

CREATE TABLE env_vars (
    id         uuid        PRIMARY KEY,
    tenant_id  uuid        NOT NULL,
    project_id uuid        NOT NULL,
    key        text        NOT NULL CHECK (key ~ '^[A-Za-z_][A-Za-z0-9_]*$'),
    -- bytea, not text: Phase 2 stores ciphertext here, which is arbitrary bytes.
    value      bytea       NOT NULL,
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL,
    UNIQUE (project_id, key),
    FOREIGN KEY (tenant_id, project_id) REFERENCES projects (tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE domains (
    id          uuid        PRIMARY KEY,
    tenant_id   uuid        NOT NULL,
    project_id  uuid        NOT NULL,
    -- Globally unique: one hostname can route to one project, across all tenants.
    hostname    text        NOT NULL UNIQUE CHECK (hostname = lower(hostname)),
    verified_at timestamptz,
    created_at  timestamptz NOT NULL,
    FOREIGN KEY (tenant_id, project_id) REFERENCES projects (tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE builds (
    id          uuid        PRIMARY KEY,
    tenant_id   uuid        NOT NULL,
    project_id  uuid        NOT NULL,
    commit_sha  text        NOT NULL CHECK (commit_sha ~ '^[0-9a-f]{40}$'),
    branch      text        NOT NULL,
    status      text        NOT NULL CHECK (status IN ('queued', 'building', 'succeeded', 'failed')),
    image_ref   text        NOT NULL DEFAULT '',
    error       text        NOT NULL DEFAULT '',
    started_at  timestamptz,
    finished_at timestamptz,
    created_at  timestamptz NOT NULL,
    updated_at  timestamptz NOT NULL,
    -- Target for deployments' foreign key: tenant, project and build must all agree.
    UNIQUE (tenant_id, project_id, id),
    FOREIGN KEY (tenant_id, project_id) REFERENCES projects (tenant_id, id) ON DELETE CASCADE
);
CREATE INDEX builds_project_created ON builds (project_id, created_at DESC);

CREATE TABLE deployments (
    id         uuid        PRIMARY KEY,
    tenant_id  uuid        NOT NULL,
    project_id uuid        NOT NULL,
    build_id   uuid        NOT NULL,
    status     text        NOT NULL CHECK (status IN ('pending', 'deploying', 'live', 'superseded', 'failed', 'stopped')),
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL,
    FOREIGN KEY (tenant_id, project_id) REFERENCES projects (tenant_id, id) ON DELETE CASCADE,
    -- A deployment's build must be a build of the same project, in the same tenant.
    FOREIGN KEY (tenant_id, project_id, build_id) REFERENCES builds (tenant_id, project_id, id) ON DELETE CASCADE
);
CREATE INDEX deployments_project_created ON deployments (project_id, created_at DESC);
-- At most one live deployment per project. Switching live (deploy, rollback) must
-- therefore demote the old one first, in one transaction (Phase 5).
CREATE UNIQUE INDEX deployments_one_live ON deployments (project_id) WHERE status = 'live';

-- Global, content-addressed: no tenant_id. Identical layers from any tenant are one row.
CREATE TABLE build_layers (
    digest     text        PRIMARY KEY CHECK (digest ~ '^sha256:[0-9a-f]{64}$'),
    size_bytes bigint      NOT NULL CHECK (size_bytes >= 0),
    created_at timestamptz NOT NULL
);

-- A layer's reference count is the number of rows here: it can't drift when a build is
-- cascade-deleted, the way a counter column would.
CREATE TABLE build_layer_refs (
    build_id     uuid    NOT NULL REFERENCES builds (id) ON DELETE CASCADE,
    position     integer NOT NULL CHECK (position >= 0),
    -- RESTRICT: the database refuses to delete a layer that some build still uses.
    layer_digest text    NOT NULL REFERENCES build_layers (digest) ON DELETE RESTRICT,
    PRIMARY KEY (build_id, position)
);
CREATE INDEX build_layer_refs_digest ON build_layer_refs (layer_digest);
